local KCookie = CS.Engine.Lib.KCookie
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local GachaponUtils = import('Game.Gachapon.GachaponUtils')
local ActivityUtils = import("Game.Activity.ActivityUtils")
local UIActivityMainSingleSignCellNode = "Game.UI.ActivityMainDialog.UIActivityMainSingleSignCellNode"
local HorizontalLayoutGroup = CS.UnityEngine.UI.HorizontalLayoutGroup
local CountDownTime = 2592000 --30 * 86400 30天的秒数
