---@class UIActivityMainSingleSignNode
---@field BtnRoleNameNode               	UnityEngine.RectTransform
---@field LayoutCrad                    	UnityEngine.UI.ScrollRect
---@field Cell                          	Engine.Modules.LuaBehaviour
---@field ImgRole                       	UnityEngine.RectTransform
---@field SingleSignListView            	UnityEngine.RectTransform
---@field ImgTitleName                  	Engine.UI.WebRawImage
---@field TextDetail                    	UnityEngine.UI.Text
---@field BtnFinalDay                   	Engine.Modules.LuaBehaviour
---@field TextPlayExplain               	UnityEngine.RectTransform
---@field TxtTime                       	UnityEngine.RectTransform

local UIActivityMainSingleSignNode = Class('UIActivityMainSingleSignNode')

function UIActivityMainSingleSignNode:__init()
    self._data = nil
    self._timeDown = nil
    self._singleSignDojo = nil        --签到内容
    self._isTomorrow = nil
end

function UIActivityMainSingleSignNode:__delete()
    self._data = nil
    self._timeDown = nil
    self._singleSignDojo = nil        --签到内容
    self._isTomorrow = nil
end

function UIActivityMainSingleSignNode:Awake()
    SetButtonAction(self.TextPlayExplain, Bind(self, self.OnBtnlllustrateClick))
    SetButtonAction(self.BtnUpDetail, Bind(self, self.OnBtnUpDetailClick))
    if isNull(self.BtnFinalDay.Env) then
        self.BtnFinalDay:Init()
    end

    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnEnableAction = Bind(self, self.OnEnable)
        self.behaviourAction = behaviourAction
    end
    CfUtils.SetImageAutoAlpha(self.ImgRole, true)
end

function UIActivityMainSingleSignNode:OnEnable()
    KTool.SetActive(self.BtnRoleNameNode, false)
end

function UIActivityMainSingleSignNode:Refresh(data,dojo)
    if not data or not dojo then
        return
    end

    self._data = data
    self._singleSignDojo = dojo
    self._isTomorrow = nil
    self:FillSelf()
    self:RefreshContent()
end

function UIActivityMainSingleSignNode:FillSelf()
    
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self._data.startTime, self._data.endTime))
    CfUtils.FillText(self.TextDetail, string.trim(self._data.detail))
    local titleImgUrl = checkString(self._data.titleImage)
    
    local confDefines  = checkTable(self._singleSignDojo.accumulativePayConf)
    KTool.SetActive(self.TextPlayExplain, checkInt(confDefines.ruleId) ~= 0)

    try(function()
        if string.len(titleImgUrl) > 0 then
            CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
        end
    end).catch (function(ex)
        print(ex)
    end)
    --self:HandleStateTimeDown()
    self:RefreshCurrencyBarInfo()
end

function UIActivityMainSingleSignNode:RefreshCurrencyBarInfo()
    local singlePanelConf = checkTable(checkTable(self._singleSignDojo).accumulativePayConf)
    ActivityUtils.RefreshNavigatorGoods(singlePanelConf.itemId)
end

--刷新内容
function UIActivityMainSingleSignNode:RefreshContent()
    self._isTomorrow = nil
    self:UpdateRoleInfo()
    self:FillFinalSignItem()
    self:FillSignLayout()
    ActivityUtils.UpdateActivityMainRedPointState(self._data.id, self:HasSign())
end

--填充签到layout列表
function UIActivityMainSingleSignNode:FillSignLayout()
    local signConf = self._singleSignDojo.accumulativePay
    local group = self.SingleSignListView.transform:GetComponent(typeof(HorizontalLayoutGroup))
    local normalCount = #signConf - 1
    if group then
        group.spacing = checkNumber(normalCount)
    end

    local count = 1
    for index, signData in ipairs(signConf) do
        if index < #signConf then
            local go = self:GetCellByIndex(count)
            self:FillItemBase(go, signData)
            count = count + 1
        end
    end
    if #signConf >= 14 then
        self:MoveLayoutToItem(normalCount)
    end
end

function UIActivityMainSingleSignNode:GetCellByIndex(index)
    local go = self.SingleSignListView.transform:Find("Cell"..index)
    if not go then
        go = CfUtils.InstantiateGo(self.Cell, self.SingleSignListView)
        go.name = "Cell"..index
    end
    return go
end

function UIActivityMainSingleSignNode:FillItemBase(go, data)
    if not go or not data then
        return
    end
    KTool.SetActive(go, true)

    local scr = CfUtils.GetLuaScr(go, UIActivityMainSingleSignCellNode)
    if self._isTomorrow == true then
        self._isTomorrow = false
    end
    if self._isTomorrow == nil and checkInt(data.status) == Constants.GetStatus.Not then
        self._isTomorrow = true
    end
    if scr then
        scr:FreshBaseUI(data, self._isTomorrow)
    end
    scr:SetBtnCallBack(function()
        if checkInt(data.status) == Constants.GetStatus.Can then
            self:DrawRequest(data.id)
        elseif checkInt(data.status) == Constants.GetStatus.Not then
            GameUtils.Toast(localize("该日签到还未达成"))
        elseif checkInt(data.status) == Constants.GetStatus.Has then
            GameUtils.Toast(localize("该日已经签过"))
        end
    end)
end

function UIActivityMainSingleSignNode:MoveLayoutToItem(spacing)
    local posY = self.SingleSignListView.transform.anchoredPosition.y
    local leftPosX = CfUtils.GetNodeRect(self.SingleSignListView).width - CfUtils.GetNodeRect(self.LayoutCrad).width
    local cellWidth = self.Cell.transform.rect.width
    local curSignId = self:FindCurrentSignId()
    local posX = leftPosX - (curSignId - 1) * cellWidth - (curSignId - 1) * spacing
    self.SingleSignListView.transform.anchoredPosition = Vector2(posX, posY)
end

--填充最后签到
function UIActivityMainSingleSignNode:FillFinalSignItem()
    local index = #self._singleSignDojo.accumulativePay
    local finalConf = self._singleSignDojo.accumulativePay[index]
    local curSignId = self:FindCurrentSignId()
    local isTomorrow = curSignId + 1 == index
    self.BtnFinalDay.Env:FreshFinalUI(finalConf, isTomorrow)
    self.BtnFinalDay.Env:SetBtnCallBack(function()
        if finalConf.status == Constants.GetStatus.Can then
            self:DrawRequest(finalConf.id)
        else
            self.BtnFinalDay.Env:ShowGoodsTips(finalConf.rewards[1])
        end
    end)
end

-- 更新立绘
function UIActivityMainSingleSignNode:UpdateRoleInfo()
    local singlePanelConf = self._singleSignDojo.accumulativePayConf
    if not singlePanelConf or next(singlePanelConf) == nil then
        return
    end
    local goodsType = GoodsUtils.GetIdType(singlePanelConf.rewardId)
    local isCardOrSkin = goodsType == Constants.IDType.CharacterCard or goodsType == Constants.IDType.CardSkin
    KTool.SetActive(self.BossDrawingNode, isCardOrSkin)
    KTool.SetActive(self.LabelRare, isCardOrSkin)
    
    if checkInt(singlePanelConf.rewardId) ~= 0 then
        KTool.SetActive(self.ImgRole, true)
        CfUtils.FillRoleImage(self.ImgRole, singlePanelConf.rewardId, Vector2(382, 242))
    end
    
    if isCardOrSkin then
        KTool.SetActive(self.BtnRoleNameNode, true)
        ---@type CommonBtnRoleNameNode
        local env = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            env:RefreshSelf(singlePanelConf.rewardId, nil, function ()
                KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._data.id)
            end, true)
        end
    end
end

function UIActivityMainSingleSignNode:DrawRequest(rewardsId)
    GameUtils.Request(
        Interfaces.ActivityDrawAccumulativeLogin,
        {activityUuid = checkInt(self._data.id), rewardId = checkInt(rewardsId) },
        function(request, response)
            if checkInt(response.errCode) == 0 then
                local data = response.data
                GoodsUtils.DrawRewards(checkTable(data.rewards), true)
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards }
                        }
                )
                self:SetSignStatusById(rewardsId)
                self:RefreshContent()
            end
        end
    )
end

function UIActivityMainSingleSignNode:FindCurrentSignId()
    local currentId = nil
    local singleSignConf = self._singleSignDojo.accumulativePay
    for index = 1, #singleSignConf do
        local itemSignData = singleSignConf[index]
        if checkInt(itemSignData.status) == Constants.GetStatus.Not then
            currentId = index == 1 and 1 or index - 1
            break
        end
    end
    if not currentId then
        currentId = #singleSignConf
    end
    return currentId
end

function UIActivityMainSingleSignNode:HasSign()
    local singleSignConf = self._singleSignDojo.accumulativePay
    local hasSign = 1
    for index = 1, #singleSignConf do
        local itemSignData = singleSignConf[index]
        if checkInt(itemSignData.status) == Constants.GetStatus.Can then
            hasSign = 0
            break
        end
    end
    return hasSign
end

function UIActivityMainSingleSignNode:SetSignStatusById(id)
    for index = 1, #self._singleSignDojo.accumulativePay do
        if self._singleSignDojo.accumulativePay[index].id == id then
            self._singleSignDojo.accumulativePay[index].status = Constants.GetStatus.Has
            break
        end
    end
end


function UIActivityMainSingleSignNode:HandleStateTimeDown()
    self:ClearTimeDown()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        CfUtils.FillText(self.TxtTime, os.date("%m/%d", self._data.startTime).."-"..os.date("%m/%d", self._data.endTime))
    end, CountDownTime, false, true)
end

function UIActivityMainSingleSignNode:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UIActivityMainSingleSignNode:OnDestroy()
    self:ClearTimeDown()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function UIActivityMainSingleSignNode:OnBtnlllustrateClick()
    if self._singleSignDojo then
        local confDefines  = checkTable(self._singleSignDojo.accumulativePayConf)
        CfUtils.ShowModuleToast(confDefines.ruleId)
    end
end

function UIActivityMainSingleSignNode:OnBtnUpDetailClick()
    local confDefines  = checkTable(self._singleSignDojo.accumulativePayConf)
    local showDrawType = checkInt(confDefines.rewardUI)

    -- preview card
    if showDrawType == Constants.RoleDisplayType.CARD then
        KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self._data.id)
        GachaponUtils.OpenDetail(confDefines.rewardId)

        -- preview skin
    elseif showDrawType == Constants.RoleDisplayType.SKIN then
        GameUtils.Toast('TODO : To be continued')

    else
        GameUtils.Toast('--== Not supported ==--')
    end
end

return UIActivityMainSingleSignNode
